  ('aa-basic', 'aa', 'Basic Economy', 1, 1, 55, 65, 200, NULL, 'https://www.aa.com/web/i18n/travel-info/baggage/checked-baggage-policy.html', 'American Airlines - Checked bag policy', NULL, '2026-11-04T17:52:04.225Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Basic Economy airport fees on tickets issued on or after 18 May 2026: 1st bag $40->$55, 2nd bag $45->$65 (American adds $5 to the 1st and 2nd bag for Basic Economy), 3rd bag $200. Prepaid prices are $50 and $60.', datetime('now')),
  ('aa-main', 'aa', 'Main Cabin', 1, 1, 50, 60, 200, NULL, 'https://www.aa.com/web/i18n/travel-info/baggage/checked-baggage-policy.html', 'American Airlines - Checked bag policy', NULL, '2026-11-04T17:52:04.225Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Main Cabin airport fees on tickets issued on or after 18 May 2026: 1st bag $40->$50, 2nd bag $45->$60, 3rd bag $200, 4th and each additional $200. Prepaid prices are $45 and $55.', datetime('now')),
  ('dl-basic', 'dl', 'Basic Economy', 1, 1, 45, 55, 200, NULL, 'https://www.delta.com/us/en/baggage/overview', 'Delta Air Lines - Baggage Overview', NULL, '2026-11-04T17:53:17.401Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Delta Main Basic airport fees: 1st bag $35->$45, 2nd bag $45->$55, 3rd bag and each additional bag $200. A carry-on bag and a personal item are included.', datetime('now')),
  ('dl-main', 'dl', 'Main Cabin', 1, 1, 45, 55, 200, NULL, 'https://www.delta.com/us/en/baggage/overview', 'Delta Air Lines - Baggage Overview', NULL, '2026-11-04T17:53:17.401Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Delta Main Classic airport fees: 1st bag $35->$45, 2nd bag $45->$55, 3rd bag and each additional bag $200. A carry-on bag and a personal item are included.', datetime('now')),
  ('ua-basic', 'ua', 'Basic Economy', 1, 0, 50, 60, 200, NULL, 'https://www.united.com/en/us/fly/baggage/checked-bags.html', 'United Airlines - Checked bags', NULL, '2026-11-04T18:08:37.138Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Basic Economy airport fees for tickets purchased on or after 3 April 2026: 1st bag $40->$50, 2nd bag $50->$60, 3rd and each additional bag $200. Basic Economy includes a personal item but no carry-on: a carry-on is checked for a fee, starting at $50 at the airport lobby and $75 at the gate.', datetime('now')),
  ('ua-main', 'ua', 'Main Cabin', 1, 1, 50, 60, 200, NULL, 'https://www.united.com/en/us/fly/baggage/checked-bags.html', 'United Airlines - Checked bags', NULL, '2026-11-04T18:08:37.138Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Economy airport fees for tickets purchased on or after 3 April 2026: 1st bag $40->$50, 2nd bag $50->$60, 3rd and each additional bag $200. Economy includes a carry-on bag and a personal item.', datetime('now')),
  ('nk-standard', 'nk', 'Standard', 1, 0, NULL, NULL, NULL, NULL, 'https://www.spirit.com/optional-services/baggage', 'Spirit Airlines - Baggage', NULL, '2026-11-04T18:15:00.460Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger (Spirit prices each bag for the route, the dates and the booking channel, so no single figure is published)', 'USD', 'verified', 'Spirit publishes no single base checked-bag price on its own pages: it says bag prices vary by dates of travel, route and channel of purchase and points travellers to its baggage calculator for the figure for their trip. The carried-over 59 and 85 dollar figures had no source, so they are now unpriced rather than quoted. A personal item is included and a carry-on is not: Spirit''s Low Fare sells the overhead bin bag and the checked bag separately.', datetime('now')),
  ('f9-standard', 'f9', 'Standard', 1, 1, NULL, NULL, NULL, NULL, 'https://www.flyfrontier.com/travel/travel-info/bag-options/', 'Frontier Airlines - Bag Options', NULL, '2026-11-04T17:46:41.680Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Frontier publishes no single base checked-bag price on its own pages: it prices bags by route and by when you buy them, and sends travellers to its Bag Price Checker. The carried-over $65/$85 figures had no source, so they are now left unpriced and the calculator reports them as not priced rather than quoting a number the airline does not publish. The personal item and the carry-on are included in every fare, so includes_carry_on is now true.', datetime('now')),
  ('wn-wanna', 'wn', 'Wanna Get Away', 1, 1, 45, 55, 150, NULL, 'https://www.southwest.com/html/customer-service/travel-fees.html', 'Southwest Airlines - Travel fees', NULL, '2026-11-04T18:09:02.088Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'The seed modelled two free checked bags. For itineraries ticketed on or after 18 April 2026 the Basic Fare charges $45 for the 1st bag and $55 for the 2nd, so first_checked_fee 0->$45 and second_checked_fee 0->$55. 3rd and each additional bag $150. A carry-on bag and a personal item remain included.', datetime('now')),
  ('as-saver', 'as', 'Saver', 1, 1, 45, 55, 200, NULL, 'https://www.alaskaair.com/content/travel-info/baggage/checked-bags', 'Alaska Airlines - Checked bags', NULL, '2026-11-04T18:05:49.760Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Saver airport fees for tickets ticketed on or after 10 April 2026: 1st bag $35->$45, 2nd bag $45->$55, 3rd bag $200, 4th and each additional bag $200. A carry-on bag and a personal item are included.', datetime('now')),
  ('as-main', 'as', 'Main', 1, 1, 45, 55, 200, NULL, 'https://www.alaskaair.com/content/travel-info/baggage/checked-bags', 'Alaska Airlines - Checked bags', NULL, '2026-11-04T18:05:49.760Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Main Cabin airport fees for tickets ticketed on or after 10 April 2026: 1st bag $35->$45, 2nd bag $45->$55, 3rd bag $200, 4th and each additional bag $200. A carry-on bag and a personal item are included.', datetime('now')),
  ('b6-bluebasic', 'b6', 'Blue Basic', 1, 0, 60, 75, 200, NULL, 'https://www.jetblue.com/help/checked-bags', 'JetBlue - Checked bags', NULL, '2026-11-04T18:04:27.071Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Main Base airport fees within 24 hours of departure on off-peak dates: 1st bag $35->$60, 2nd bag $50->$75. Peak dates are $70 and $85; prepaid more than 24 hours ahead it is $50 off-peak and $55 peak. The 3rd or more checked bag is $200. Main Base includes a carry-on bag and a personal item.', datetime('now')),
  ('b6-blue', 'b6', 'Blue', 1, 1, 60, 75, 200, NULL, 'https://www.jetblue.com/help/checked-bags', 'JetBlue - Checked bags', NULL, '2026-11-04T18:04:27.071Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Blue airport fees within 24 hours of departure on off-peak dates: 1st bag $35->$60, 2nd bag $50->$75. Peak dates are $70 and $85; prepaid more than 24 hours ahead it is $50 off-peak and $55 peak. The 3rd or more checked bag is $200. Blue includes a carry-on bag and a personal item.', datetime('now')),
  ('ba-economy', 'ba', 'Economy', 1, 1, 0, 90, 175, NULL, 'https://www.britishairways.com/en-gb/information/baggage-essentials', 'British Airways - Baggage essentials', NULL, '2026-11-04T18:09:17.739Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'International, London Heathrow to New York JFK, Economy, one-way, per passenger, paid at the airport', 'GBP', 'verified', 'Economy includes one hold bag, so the first checked bag is 0 GBP. The second bag is 90 GBP at the airport (65 GBP online) and the third is 175 GBP at the airport (130 GBP online), read from British Airways'' own baggage calculator for London Heathrow to New York JFK in Economy. Prices are route- and date-specific: British Airways says the cost of each extra hold bag depends on the destination.', datetime('now')),
  ('ba-economy-basic', 'ba', 'Economy Basic', 1, 1, 75, 90, 175, NULL, 'https://www.britishairways.com/en-gb/information/baggage-essentials', 'British Airways - Baggage essentials', NULL, '2026-11-04T18:09:17.739Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'International, London Heathrow to New York JFK, Economy, one-way, per passenger, paid at the airport', 'GBP', 'verified', 'Economy Basic carries no hold bag, so the first checked bag costs 75 GBP at the airport (55 GBP online) rather than being included. The second bag is 90 GBP and the third 175 GBP at the airport, read from British Airways'' own baggage calculator for London Heathrow to New York JFK.', datetime('now')),
  ('ac-basic', 'ac', 'Economy Basic', 1, 0, 45, 60, 100, NULL, 'https://www.aircanada.com/us/en/aco/home/legal/products-and-services.html', 'Air Canada - Products and services (baggage)', NULL, '2026-11-04T18:07:17.776Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'Canada to the U.S., Economy, one-way, per passenger, paid at the airport (Air Canada prints a tax-inclusive range and a pre-tax base amount; the pre-tax base is recorded)', 'USD', 'verified', 'Economy Basic between Canada and the U.S.: 1st bag 45 USD (45-54 with tax), 2nd bag 60 USD (60-72), each additional bag 100 USD (100-120). Economy Basic includes a personal item but not a carry-on on most itineraries for tickets purchased on or after 3 January 2025.', datetime('now')),
  ('ac-main', 'ac', 'Economy Standard', 1, 1, 45, 60, 100, NULL, 'https://www.aircanada.com/us/en/aco/home/legal/products-and-services.html', 'Air Canada - Products and services (baggage)', NULL, '2026-11-04T18:07:17.776Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'Canada to the U.S., Economy, one-way, per passenger, paid at the airport (Air Canada prints a tax-inclusive range and a pre-tax base amount; the pre-tax base is recorded)', 'USD', 'verified', 'Economy Standard between Canada and the U.S.: 1st bag 45 USD (45-54 with tax), 2nd bag 60 USD (60-72), each additional bag 100 USD (100-120). A carry-on bag and a personal item are included. Flex fares include the first bag free; Latitude includes two.', datetime('now')),
  ('ws-basic', 'ws', 'UltraBasic', 1, 0, 80, NULL, 160, NULL, 'https://www.westjet.com/en-us/flights/fees', 'WestJet - Service fees', NULL, '2026-11-04T17:51:11.846Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'Within Canada and the U.S., Econo, one-way, per passenger, paid at the airport (WestJet publishes a tax-inclusive range; the lowest published figure is recorded and the range noted)', 'USD', 'verified', 'UltraBasic at the airport within Canada and the U.S.: 1st bag 80-94 USD, 3rd and 4th bag 160-189 USD. The 2nd bag price is not published separately for UltraBasic. UltraBasic includes one personal item and no carry-on, except to and from Europe and Asia and where Extended Comfort has been bought.', datetime('now')),
  ('ws-main', 'ws', 'Econo', 1, 1, 70, 85, 160, NULL, 'https://www.westjet.com/en-us/flights/fees', 'WestJet - Service fees', NULL, '2026-11-04T17:51:11.846Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'Within Canada and the U.S., Econo, one-way, per passenger, paid at the airport (WestJet publishes a tax-inclusive range; the lowest published figure is recorded and the range noted)', 'USD', 'verified', 'Econo at the airport within Canada and the U.S.: 1st bag 70-83 USD, 2nd bag 85-100 USD, 3rd and 4th bag 160-189 USD. Prepaid prices are lower (45-53 and 60-71) and online check-in sits between the two. WestJet Rewards member benefits apply instead of these fares.', datetime('now')),
  ('lh-basic', 'lh', 'Economy Light', 1, 0, 90, 90, 300, NULL, 'https://www.lufthansa.com/us/en/current-fees', 'Lufthansa - Current fees', NULL, '2026-11-04T17:57:36.481Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'United States to Germany, Economy Class, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Economy Light and Basic carry no free hold bag. The first checked bag can be added at a discounted rate of 90 USD at check-in for Intercontinental (USA/Canada) routes, and the second bag is 90 USD at the airport on a United States to Germany itinerary. A carry-on must be bought in advance: it cannot be purchased at the airport.', datetime('now')),
  ('lh-main', 'lh', 'Economy Class', 1, 1, 0, 90, 300, NULL, 'https://www.lufthansa.com/us/en/current-fees', 'Lufthansa - Current fees', NULL, '2026-11-04T17:57:36.481Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'United States to Germany, Economy Class, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Economy Class on a United States to Germany itinerary: the first checked bag up to 23 kg is free, the second costs 90 USD at the airport, and each additional standard bag costs 300 USD at the check-in desk on long-haul intercontinental routes. A carry-on up to 8 kg and a personal item are included.', datetime('now')),
  ('ei-saver', 'ei', 'Saver', 1, 0, 100, 100, NULL, NULL, 'https://webcheckin.aerlingus.com/plan-and-book/plan/fare-types/', 'Aer Lingus - Fare types', NULL, '2026-11-04T18:16:36.396Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'Transatlantic, one-way, per passenger (Aer Lingus prices bags by destination distance and by booking channel; the published 23 kg airport rate is recorded)', 'USD', 'verified', 'Saver is the lowest fare and carries no hold bag. Aer Lingus publishes per-bag weight rates rather than a per-bag-number ladder: at the airport for a 23 kg (50 lb) bag every fare type costs 100 USD (75 EUR / 65 GBP / 100 CAD), and up to two additional bags may be bought at that same published rate. Online, a Saver fare for a 20 kg bag costs 54.99 USD. A maximum of three checked bags is permitted per guest per direction. A Saver fare can pay to take a bag on board or check a 10 kg bag into the hold for free.', datetime('now')),
  ('sy-standard', 'sy', 'Standard', 1, 0, NULL, NULL, NULL, NULL, 'https://suncountry.com/bags-optional-services', 'Sun Country Airlines - Bags and Optional Services', NULL, '2026-11-04T18:22:01.745Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, one-way, per passenger, paid at the airport (Sun Country prices each bag for each flight, so it publishes no single base fee)', 'USD', 'verified', 'Sun Country publishes no single base bag price: its own page says bag prices vary by flight and sends travellers to Explore Bag Prices for the figure for their trip, and the carried-over figures had no source, so the base fee and the overhead carry-on fee are left unpriced and the calculator reports them as not priced. The under-seat item is included on every fare; the overhead bag is a paid add-on.', datetime('now')),
  ('ha-main', 'ha', 'Main Cabin', 1, 1, 40, 45, 150, NULL, 'https://www.hawaiianairlines.com/content/travel-info/baggage/checked-bags', 'Hawaiian Airlines - Checked baggage fees and policies', NULL, '2026-11-04T18:02:50.706Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport (Hawaiian prints the prepaid price alongside the airport price)', 'USD', 'verified', 'Main Cabin standard bag: 1st checked bag 40 USD (35 USD prepaid), 2nd 45 USD, 3rd 150 USD, 4th and each additional bag 150 USD. A carry-on bag and a personal item are included.', datetime('now')),
  ('ha-basic', 'ha', 'Basic Economy', 1, 0, 40, 45, 150, NULL, 'https://www.hawaiianairlines.com/content/travel-info/baggage/checked-bags', 'Hawaiian Airlines - Checked baggage fees and policies', NULL, '2026-11-04T18:02:50.706Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport (Hawaiian prints the prepaid price alongside the airport price)', 'USD', 'verified', 'Basic Economy standard bag: 1st checked bag 40 USD (35 USD prepaid), 2nd 45 USD, 3rd 150 USD, 4th and each additional bag 150 USD. Basic Economy does not include a full-size carry-on on most domestic routes, but a personal item is still permitted.', datetime('now')),
  ('g4-standard', 'g4', 'Standard', 1, 0, NULL, NULL, NULL, NULL, 'https://www.allegiantair.com/baggage-1', 'Allegiant Air - Carry-On and Checked Baggage Policy, Size & Fees', NULL, '2026-11-04T17:53:15.013Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger (Allegiant prices every bag for the route and the date, and its own calculator labels its figures estimates)', 'USD', 'verified', 'Allegiant publishes no fixed bag price: its own bag fee calculator produces per-route estimates and labels them as such. The base checked-bag fee and the carry-on fee are left unpriced and the calculator reports them as not priced. One personal item is included free; the carry-on and checked bags are paid add-ons.', datetime('now')),
  ('bz-standard', 'bz', 'Standard', 1, 0, NULL, NULL, NULL, NULL, 'https://www.flybreeze.com/fly-with-us/bag-pricing', 'Breeze Airways - Bag Pricing', NULL, '2026-11-04T17:55:17.763Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger (Breeze prices every bag for the booking session, so no single figure is published)', 'USD', 'verified', 'Breeze publishes no single base bag price: its own bag pricing page states that the prices displayed apply to the current web browser session and that existing bookings should be checked through My Trips. The base checked-bag fee and the carry-on fee are left unpriced and the calculator reports them as not priced. One personal item is included free on every fare; carry-on and checked bags are sold separately or in bundles.', datetime('now')),
  ('av-standard', 'av', 'Standard', 1, 0, 49, 49, 49, 54, 'https://www.aveloair.com/optional-services', 'Avelo Airlines - Optional Services', NULL, '2026-11-04T17:50:39.682Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger (Avelo publishes a "from" price that rises with the route and the time of purchase)', 'USD', 'verified', 'Avelo charges a flat price per bag, "from $49 to $75" for a checked bag and "from $54 to $75" for the overhead carry-on, so the lowest published figure is recorded for each. Up to ten checked bags may be bought per traveller, each at the same per-bag price. One personal item is included free; the carry-on and checked bags are paid add-ons, and pre-paying costs less.', datetime('now'));

